ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-valuation-20261002';DATA=ROOT/'data/btc-valuation-20261002'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');fore=read(RUN/'forecast-summary.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');assert len(s)==v['accounts']==48 and rep['all_bytes_equal'] and not sel['passed'];rows=[];base=[];annual=[];cost=[];ci=[]
 for n in ('VA_INC','VA_PRICE','VA_VALUE','VA_INV'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='VA_INC' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]]);cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.2f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('E_SPOT','VA_PRICE','VA_VALUE'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 evidence={'build':'1002v1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'forecast':fore,'uncertainty':unc,'diagnostics':diag,'information_age':read(RUN/'information-age.json'),'source_audit':read(DATA/'audit.json'),'scope':'BTC-only development; UTXO movement valuation is not true holder acquisition cost; no accepted strategy'};(DOWN/'btc-valuation-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-valuation-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-valuation-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
